<script setup lang="ts">import { Head, Link } from '@inertiajs/vue3'; type Line = { presentation: string; sku: string; quantity_in: string; quantity_out: string; unit_cost: number; balance_after: string }; type Movement = { id: string; document_number: string; movement_type: string; status: string; effective_at: string; creator: string; notes: string | null; lines: Line[] }; defineProps<{ movements: { data: Movement[] } }>(); const money = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 });</script>
<template><Head title="Kardex" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between gap-3"><div><h1 class="text-2xl font-semibold">Kardex</h1><p class="text-sm text-muted-foreground">Libro inmutable de entradas y salidas de inventario.</p></div><Link href="/inventory" class="text-sm font-medium text-amber-700 hover:underline">Volver al inventario</Link></header><section class="space-y-3"><details v-for="movement in movements.data" :key="movement.id" class="rounded-xl border bg-card p-4"><summary class="cursor-pointer list-none"><div class="flex flex-col justify-between gap-2 sm:flex-row"><div><p class="font-medium">{{ movement.document_number }} · {{ movement.movement_type }}</p><p class="text-xs text-muted-foreground">{{ movement.creator }} · {{ movement.effective_at }}</p></div><span class="text-sm">{{ movement.status }}</span></div></summary><div class="mt-4 overflow-x-auto border-t pt-3"><p v-if="movement.notes" class="mb-3 text-sm text-muted-foreground">{{ movement.notes }}</p><table class="w-full text-sm"><thead class="text-left"><tr><th class="py-2">Presentación</th><th class="py-2 text-right">Entrada</th><th class="py-2 text-right">Salida</th><th class="py-2 text-right">Costo</th><th class="py-2 text-right">Saldo</th></tr></thead><tbody><tr v-for="line in movement.lines" :key="line.sku" class="border-t"><td class="py-2">{{ line.presentation }} <code class="text-xs">{{ line.sku }}</code></td><td class="py-2 text-right">{{ line.quantity_in }}</td><td class="py-2 text-right">{{ line.quantity_out }}</td><td class="py-2 text-right">{{ money.format(line.unit_cost) }}</td><td class="py-2 text-right">{{ line.balance_after }}</td></tr></tbody></table></div></details><p v-if="movements.data.length === 0" class="rounded-xl border p-10 text-center text-sm text-muted-foreground">Aún no existen movimientos.</p></section></main></template>
